import{NextResponse}from"next/server";import{prisma}from"@/lib/prisma";const n=(v:unknown)=>Number(v??0);const bd=(v:string|null,end=false)=>v?new Date(`${v}T${end?"23:59:59.999":"00:00:00.000"}`):undefined;
export async function GET(request:Request){try{const p=new URL(request.url).searchParams,from=bd(p.get("from")),to=bd(p.get("to"),true),ids=(p.get("itemIds")??"").split(",").map(Number).filter(x=>x>0),date={...(from?{gte:from}:{}),...(to?{lte:to}:{})},[trades,costs,expenses,items]=await Promise.all([prisma.externalTrade.findMany({where:{...(from||to?{tradeDate:date}:{}),...(ids.length?{itemId:{in:ids}}:{})},include:{item:true},orderBy:{tradeDate:"desc"}}),prisma.externalLinkedCost.findMany({where:{...(from||to?{costDate:date}:{}),...(ids.length?{itemId:{in:ids}}:{})},include:{item:true,externalTrade:true},orderBy:{costDate:"desc"}}),prisma.externalExpense.findMany({where:from||to?{expenseDate:date}:{},orderBy:{expenseDate:"desc"}}),prisma.item.findMany({where:{isActive:true},select:{id:true,code:true,nameAr:true},orderBy:{nameAr:"asc"}})]);const report=new Map<number,Row>();type Row={itemId:number;itemName:string;purchasedQty:number;purchasedValue:number;soldQty:number;salesValue:number;transportCost:number;otherCost:number;totalCost:number;netProfit:number;margin:number;profitPerTon:number};for(const t of trades){const r=report.get(t.itemId)??{itemId:t.itemId,itemName:t.item.nameAr,purchasedQty:0,purchasedValue:0,soldQty:0,salesValue:0,transportCost:0,otherCost:0,totalCost:0,netProfit:0,margin:0,profitPerTon:0};if(t.tradeType==="PURCHASE"){r.purchasedQty+=n(t.quantity);r.purchasedValue+=n(t.totalAmount)}else{r.soldQty+=n(t.quantity);r.salesValue+=n(t.totalAmount)}report.set(t.itemId,r)}for(const x of costs){const r=report.get(x.itemId)??{itemId:x.itemId,itemName:x.item.nameAr,purchasedQty:0,purchasedValue:0,soldQty:0,salesValue:0,transportCost:0,otherCost:0,totalCost:0,netProfit:0,margin:0,profitPerTon:0};if(x.costType==="TRANSPORT")r.transportCost+=n(x.amount);else r.otherCost+=n(x.amount);report.set(x.itemId,r)}const rows=[...report.values()].map(r=>{r.totalCost=r.purchasedValue+r.transportCost+r.otherCost;r.netProfit=r.salesValue-r.totalCost;r.margin=r.salesValue?r.netProfit/r.salesValue*100:0;r.profitPerTon=r.soldQty?r.netProfit/r.soldQty:0;return r});return NextResponse.json({trades,costs,expenses,items,report:rows,summary:rows.reduce((s,r)=>({sales:s.sales+r.salesValue,cost:s.cost+r.totalCost,profit:s.profit+r.netProfit}),{sales:0,cost:0,profit:0})})}catch(e){console.error(e);return NextResponse.json({error:"تعذر تحميل العمليات الخارجية"},{status:500})}}
